-- Lote 4 de recetas seed: británicas/porridge, asiáticas, Jaén/Andalucía y
-- fáciles del día a día (70 recetas).
--
-- OJO: este lote YA ESTÁ APLICADO en producción (sembrado directo a BD el
-- 2026-06-11 vía `pdh recipes:seed`). El guard de abajo lo hace idempotente:
-- solo siembra si el lote no está ya en el catálogo.

do $batch4$
begin
  if exists (select 1 from recipes where household_id is null and name = 'Pipirrana de Jaén') then
    raise notice 'Lote 4 ya sembrado, no se hace nada';
    return;
  end if;

  -- Clásicos británicos y porridges (16)
  perform seed_recipe($json${"nombre": "Porridge inglés tradicional", "descripcion": "El clásico británico: avena cremosa cocida en leche con una pizca de sal y miel por encima.", "instrucciones": "Pon la avena, la leche y la sal en un cazo\nCuece a fuego medio 5-7 min removiendo\nSirve con la miel por encima", "raciones": 2, "prep_min": 2, "cocina_min": 8, "tags": ["desayuno", "rapida", "sin-horno", "dulce", "veggie"], "principal": "avena", "ingredientes": [{"n": "avena", "q": 80, "u": "g"}, {"n": "leche", "q": 500, "u": "ml"}, {"n": "sal", "q": 0.25, "u": "cdta"}, {"n": "miel", "q": 1.5, "u": "cda"}]}$json$::jsonb);
  perform seed_recipe($json${"nombre": "Porridge de manzana y canela", "descripcion": "Porridge templado con manzana salteada, pasas y canela, estilo apple pie.", "instrucciones": "Cuece la avena con la leche 5 min\nSaltea la manzana en dados con la canela\nMezcla con las pasas y la miel y sirve", "raciones": 2, "prep_min": 5, "cocina_min": 10, "tags": ["desayuno", "rapida", "sin-horno", "dulce", "veggie"], "temporada": "otono", "principal": "avena", "ingredientes": [{"n": "avena", "q": 80, "u": "g"}, {"n": "leche", "q": 450, "u": "ml"}, {"n": "manzana", "q": 1, "u": "pieza"}, {"n": "canela", "q": 1, "u": "cdta"}, {"n": "pasas", "q": 20, "u": "g"}, {"n": "miel", "q": 1, "u": "cda"}]}$json$::jsonb);
  perform seed_recipe($json${"nombre": "Porridge de dátiles y nueces", "descripcion": "Avena cocida en bebida de avena con dátiles troceados y nueces: dulzor sin azúcar añadido.", "instrucciones": "Trocea los dátiles y cuécelos con la avena y la bebida de avena 6 min\nSirve con las nueces picadas y la canela", "raciones": 2, "prep_min": 3, "cocina_min": 8, "tags": ["desayuno", "rapida", "sin-horno", "dulce", "veggie"], "principal": "avena", "ingredientes": [{"n": "avena", "q": 80, "u": "g"}, {"n": "bebida de avena", "q": 500, "u": "ml"}, {"n": "dátiles", "q": 4, "u": "pieza"}, {"n": "nueces", "q": 30, "u": "g"}, {"n": "canela", "q": 0.5, "u": "cdta"}]}$json$::jsonb);
  perform seed_recipe($json${"nombre": "Porridge de pera y chocolate negro", "descripcion": "Porridge goloso con pera en dados y chocolate negro fundido en el calor de la avena.", "instrucciones": "Cuece la avena con la leche 6 min\nAñade la pera en dados\nSirve con el chocolate troceado por encima para que se funda", "raciones": 2, "prep_min": 3, "cocina_min": 8, "tags": ["desayuno", "rapida", "sin-horno", "dulce", "veggie"], "principal": "avena", "ingredientes": [{"n": "avena", "q": 80, "u": "g"}, {"n": "leche", "q": 450, "u": "ml"}, {"n": "pera", "q": 1, "u": "pieza"}, {"n": "chocolate negro", "q": 25, "u": "g"}]}$json$::jsonb);
  perform seed_recipe($json${"nombre": "Porridge de plátano y crema de cacahuete", "descripcion": "Avena cremosa con plátano machacado dentro y crema de cacahuete por encima: saciante total.", "instrucciones": "Machaca medio plátano y cuécelo con la avena y la leche 6 min\nSirve con el resto del plátano en rodajas y la crema de cacahuete", "raciones": 2, "prep_min": 3, "cocina_min": 8, "tags": ["desayuno", "rapida", "sin-horno", "dulce", "veggie"], "principal": "avena", "ingredientes": [{"n": "avena", "q": 80, "u": "g"}, {"n": "leche", "q": 450, "u": "ml"}, {"n": "plátano", "q": 2, "u": "pieza"}, {"n": "crema de cacahuete", "q": 1.5, "u": "cda"}]}$json$::jsonb);
  perform seed_recipe($json${"nombre": "Desayuno inglés completo (full English)", "descripcion": "Huevos, bacon, salchichas, alubias en tomate, champiñones y tomate a la plancha: el brunch británico.", "instrucciones": "Haz las salchichas y el bacon en la sartén y reserva\nSaltea los champiñones y el tomate partido\nCalienta las alubias con el tomate frito\nHaz los huevos a la plancha\nSirve todo junto con el pan", "raciones": 2, "prep_min": 10, "cocina_min": 20, "tags": ["desayuno", "sin-horno"], "principal": "huevo", "ingredientes": [{"n": "huevo", "q": 2, "u": "pieza"}, {"n": "bacon", "q": 80, "u": "g"}, {"n": "salchichas frescas", "q": 2, "u": "pieza"}, {"n": "alubias blancas cocidas", "q": 200, "u": "g"}, {"n": "tomate frito", "q": 80, "u": "g"}, {"n": "champiñones", "q": 150, "u": "g"}, {"n": "tomate", "q": 2, "u": "pieza"}, {"n": "pan", "q": 1, "u": "pieza"}]}$json$::jsonb);
  perform seed_recipe($json${"nombre": "Beans on toast con queso", "descripcion": "Alubias en salsa de tomate ligeramente dulce sobre pan tostado con queso fundido: el básico británico.", "instrucciones": "Calienta las alubias con el tomate frito y el azúcar moreno 5 min\nTuesta el pan de molde\nVierte las alubias encima y termina con el queso rallado", "raciones": 2, "prep_min": 3, "cocina_min": 8, "tags": ["rapida", "sin-horno", "veggie"], "principal": "legumbre", "ingredientes": [{"n": "alubias blancas cocidas", "q": 300, "u": "g"}, {"n": "tomate frito", "q": 150, "u": "g"}, {"n": "azúcar moreno", "q": 1, "u": "cda"}, {"n": "pan de molde", "q": 4, "u": "pieza"}, {"n": "queso rallado", "q": 50, "u": "g"}]}$json$::jsonb);
  perform seed_recipe($json${"nombre": "Cottage pie británico", "descripcion": "Carne picada guisada con verduras bajo un manto de puré de patata gratinado.", "instrucciones": "Sofríe cebolla y zanahoria, añade la carne y dora\nMoja con el caldo, añade los guisantes y reduce 10 min\nCuece las patatas y haz un puré con mantequilla y leche\nCubre la carne con el puré y gratina 15 min a 200ºC", "raciones": 4, "prep_min": 20, "cocina_min": 40, "tags": ["horno", "guiso", "batch"], "temporada": "invierno", "batch_days": 2, "principal": "ternera", "ingredientes": [{"n": "carne picada de ternera", "q": 500, "u": "g"}, {"n": "cebolla", "q": 1, "u": "pieza"}, {"n": "zanahoria", "q": 2, "u": "pieza"}, {"n": "guisantes", "q": 100, "u": "g"}, {"n": "caldo de pollo", "q": 200, "u": "ml"}, {"n": "patata", "q": 5, "u": "pieza"}, {"n": "mantequilla", "q": 30, "u": "g"}, {"n": "leche", "q": 100, "u": "ml"}]}$json$::jsonb);
  perform seed_recipe($json${"nombre": "Fish and chips al horno", "descripcion": "Merluza crujiente empanada y patatas gajo al horno: la versión casera y ligera del clásico.", "instrucciones": "Corta las patatas en gajos y hornéalas 25 min a 220ºC\nPasa la merluza por harina, huevo y pan rallado\nAñádela a la bandeja y hornea 12 min más\nSirve con limón", "raciones": 2, "prep_min": 15, "cocina_min": 40, "tags": ["horno"], "principal": "pescado", "ingredientes": [{"n": "merluza", "q": 400, "u": "g"}, {"n": "patata", "q": 4, "u": "pieza"}, {"n": "harina de trigo", "q": 40, "u": "g"}, {"n": "huevo", "q": 1, "u": "pieza"}, {"n": "pan rallado", "q": 60, "u": "g"}, {"n": "limón", "q": 1, "u": "pieza"}, {"n": "aceite de oliva", "q": 2, "u": "cda"}]}$json$::jsonb);
  perform seed_recipe($json${"nombre": "Kedgeree de arroz y caballa", "descripcion": "Arroz especiado con curry, caballa desmigada y huevo duro: desayuno-cena angloindio.", "instrucciones": "Cuece los huevos 10 min\nSofríe la cebolla con el curry\nAñade el arroz y cuece con agua según paquete\nIncorpora los guisantes y la caballa desmigada\nSirve con el huevo en cuartos y limón", "raciones": 2, "prep_min": 10, "cocina_min": 25, "tags": ["sin-horno", "fiambrera"], "principal": "pescado", "ingredientes": [{"n": "arroz basmati", "q": 180, "u": "g"}, {"n": "caballa en lata", "q": 160, "u": "g"}, {"n": "huevo", "q": 2, "u": "pieza"}, {"n": "curry", "q": 2, "u": "cdta"}, {"n": "cebolla", "q": 1, "u": "pieza"}, {"n": "guisantes", "q": 80, "u": "g"}, {"n": "limón", "q": 0.5, "u": "pieza"}, {"n": "aceite de oliva", "q": 1, "u": "cda"}]}$json$::jsonb);
