  perform seed_recipe($json${"nombre": "Coronation chicken en sándwich", "descripcion": "Pollo en salsa cremosa de curry con pasas, el relleno creado para la coronación de Isabel II.", "instrucciones": "Cuece la pechuga 12 min y desmenúzala\nMezcla mayonesa, yogur, curry y pasas\nEnvuelve el pollo en la salsa\nRellena los panes tostados", "raciones": 2, "prep_min": 10, "cocina_min": 15, "tags": ["rapida", "fiambrera", "sin-horno"], "principal": "pollo", "ingredientes": [{"n": "pechuga de pollo", "q": 300, "u": "g"}, {"n": "mayonesa", "q": 2, "u": "cda"}, {"n": "yogur natural", "q": 1, "u": "pieza"}, {"n": "curry", "q": 2, "u": "cdta"}, {"n": "pasas", "q": 30, "u": "g"}, {"n": "pan de molde", "q": 4, "u": "pieza"}]}$json$::jsonb);
  perform seed_recipe($json${"nombre": "Crumble de manzana y avena", "descripcion": "Manzana asada con canela bajo una cobertura crujiente de avena y mantequilla.", "instrucciones": "Trocea las manzanas y repártelas en una fuente con canela\nMezcla avena, harina, azúcar moreno y mantequilla fría hasta hacer migas\nCubre la fruta y hornea 35 min a 180ºC", "raciones": 4, "prep_min": 15, "cocina_min": 35, "tags": ["horno", "dulce", "veggie"], "temporada": "otono", "principal": "manzana", "ingredientes": [{"n": "manzana", "q": 4, "u": "pieza"}, {"n": "avena", "q": 100, "u": "g"}, {"n": "harina de trigo", "q": 60, "u": "g"}, {"n": "azúcar moreno", "q": 4, "u": "cda"}, {"n": "mantequilla", "q": 80, "u": "g"}, {"n": "canela", "q": 1, "u": "cdta"}]}$json$::jsonb);
